-- Pure-arithmetic XOR keeps this script portable across Lua 5.2 - 5.4.
local function bxor(a, b)
    local result, place = 0, 1
    while a > 0 or b > 0 do
        local x, y = a % 2, b % 2
        if x ~= y then result = result + place end
        a = (a - x) / 2
        b = (b - y) / 2
        place = place * 2
    end
    return result
end

local function crc16(bytes)
    local crc = 0xFFFF
    for i = 0, bytes:len() - 1 do
        crc = bxor(crc, bytes:get_index(i) * 256)
        for _ = 1, 8 do
            if crc >= 0x8000 then
                crc = bxor((crc * 2) % 0x10000, 0x1021)
            else
                crc = (crc * 2) % 0x10000
            end
        end
    end
    return crc
end

