function proto.dissector(buf, pinfo, tree)
    if buf:len() < HEADER_LEN + CRC_LEN or buf(0, 1):uint() ~= SYNC then
        return 0
    end
    pinfo.cols.protocol = proto.name
    local root = tree:add(proto, buf(), proto.description)
    root:add(f.sync, buf(0, 1))
    local version_item = root:add(f.version, buf(1, 1))
    root:add_le(f.msg_id, buf(2, 2))
    root:add_le(f.length, buf(4, 2))
    local version = buf(1, 1):uint()
    local id = buf(2, 2):le_uint()
    local payload_len = buf(4, 2):le_uint()
    local total = HEADER_LEN + payload_len + CRC_LEN
    if buf:len() < total then
        root:add_proto_expert_info(ef_malformed, "Truncated frame: " .. total .. " bytes required")
        return buf:len()
    end
    if version == 0 or version > MAX_VERSION then
        version_item:add_proto_expert_info(ef_version)
    end

    local entry = MESSAGES[id]
    if entry == nil then
        pinfo.cols.info = string.format("Unknown message %d", id)
        root:add_proto_expert_info(ef_unknown)
    else
        pinfo.cols.info = entry.name
        if version < entry.since then
            version_item:add_proto_expert_info(ef_version)
        end
        if payload_len ~= entry.size then
            root:add_proto_expert_info(ef_malformed, string.format("%s needs %d payload bytes, got %d", entry.name, entry.size, payload_len))
        else
            local payload = buf(HEADER_LEN, payload_len)
            entry.dissect(payload, root:add(payload, entry.name))
        end
    end

    local crc_range = buf(HEADER_LEN + payload_len, CRC_LEN)
    local crc_item = root:add_le(f.crc, crc_range)
    local computed = crc16(buf(1, HEADER_LEN - 1 + payload_len):bytes())
    if computed == crc_range:le_uint() then
        crc_item:append_text(" [correct]")
    else
        crc_item:append_text(string.format(" [incorrect, expected 0x%04x]", computed))
        crc_item:add_proto_expert_info(ef_bad_crc)
    end
    return total
end

